DROP SCHEMA IF EXISTS steam_oltp CASCADE;
CREATE SCHEMA steam_oltp;
SET search_path TO steam_oltp;
CREATE TABLE countries (country_id SERIAL PRIMARY KEY, country_code CHAR(2) UNIQUE NOT NULL, country_name VARCHAR(100) NOT NULL, region VARCHAR(100) NOT NULL);
CREATE TABLE users (user_id SERIAL PRIMARY KEY, username VARCHAR(50) UNIQUE NOT NULL, email VARCHAR(120) UNIQUE NOT NULL, country_id INT NOT NULL REFERENCES countries(country_id), registration_date DATE NOT NULL);
CREATE TABLE developers (developer_id SERIAL PRIMARY KEY, developer_name VARCHAR(120) UNIQUE NOT NULL, country_id INT REFERENCES countries(country_id));
CREATE TABLE publishers (publisher_id SERIAL PRIMARY KEY, publisher_name VARCHAR(120) UNIQUE NOT NULL, country_id INT REFERENCES countries(country_id));
CREATE TABLE games (game_id SERIAL PRIMARY KEY, game_slug VARCHAR(120) UNIQUE NOT NULL, title VARCHAR(160) NOT NULL, developer_id INT NOT NULL REFERENCES developers(developer_id), publisher_id INT NOT NULL REFERENCES publishers(publisher_id), release_date DATE NOT NULL, base_price NUMERIC(10,2) NOT NULL CHECK (base_price >= 0), age_rating VARCHAR(10) NOT NULL);
CREATE TABLE genres (genre_id SERIAL PRIMARY KEY, genre_name VARCHAR(80) UNIQUE NOT NULL);
CREATE TABLE game_genres (game_id INT NOT NULL REFERENCES games(game_id), genre_id INT NOT NULL REFERENCES genres(genre_id), PRIMARY KEY (game_id, genre_id));
CREATE TABLE purchases (purchase_id SERIAL PRIMARY KEY, purchase_code VARCHAR(30) UNIQUE NOT NULL, user_id INT NOT NULL REFERENCES users(user_id), game_id INT NOT NULL REFERENCES games(game_id), purchase_date DATE NOT NULL, paid_amount NUMERIC(10,2) NOT NULL CHECK (paid_amount >= 0), discount_percent INT NOT NULL CHECK (discount_percent BETWEEN 0 AND 100), payment_method VARCHAR(30) NOT NULL);
CREATE TABLE reviews (review_id SERIAL PRIMARY KEY, review_code VARCHAR(30) UNIQUE NOT NULL, user_id INT NOT NULL REFERENCES users(user_id), game_id INT NOT NULL REFERENCES games(game_id), review_date DATE NOT NULL, rating INT NOT NULL CHECK (rating BETWEEN 1 AND 5), comment TEXT);
CREATE TABLE achievements (achievement_id SERIAL PRIMARY KEY, achievement_code VARCHAR(140) UNIQUE NOT NULL, game_id INT NOT NULL REFERENCES games(game_id), achievement_name VARCHAR(120) NOT NULL, points INT NOT NULL CHECK (points > 0));
CREATE TABLE user_achievements (user_id INT NOT NULL REFERENCES users(user_id), achievement_id INT NOT NULL REFERENCES achievements(achievement_id), earned_date DATE NOT NULL, PRIMARY KEY (user_id, achievement_id));
CREATE TABLE wishlist (user_id INT NOT NULL REFERENCES users(user_id), game_id INT NOT NULL REFERENCES games(game_id), added_date DATE NOT NULL, PRIMARY KEY (user_id, game_id));
CREATE TABLE price_history (price_history_id SERIAL PRIMARY KEY, game_id INT NOT NULL REFERENCES games(game_id), valid_from DATE NOT NULL, valid_to DATE, price NUMERIC(10,2) NOT NULL CHECK (price >= 0), currency CHAR(3) NOT NULL DEFAULT 'EUR', UNIQUE (game_id, valid_from));
